ITEMS = [
 {"n": 1, "q": {"tr": "Harfin ve harf-i cerrin tarifi nedir? Harf-i cerler hangi mânâlara gelir?", "en": "How are the particle and the jarr letter defined, and what meanings do the jarr letters carry?"},
  "a": {"tr": "Harf: başkasındaki bir mânâya delâlet edendir. Harf-i cer: bir fiili ya da fiil mânâsını kendisinden sonrakine ulaştırmak için konulandır. مِنْ ibtidâ, tebyîn, teb'îz (gayr-i mûcib kelâmda zâid); إِلَى intihâ (bazen مَعَ); حَتَّى gâye (çokça مَعَ); فِي zarfiyet; بِ ilsâk, istiâne, musâhabe, mukâbele, ta'diye, zarfiyet (nefiy ve istifhamın haberinde kıyâsen zâid); لِ ta'lîl, tahsîs (bazen zâid); رُبَّ taklîl; وَاوُ الْقَسَم fiil hazfedilince isme mahsus kasem; تَاءُ الْقَسَم lafza-i celâle mahsus; عَنْ bu'd ve mücâvezet; عَلَى isti'lâ; كَ teşbîh (bazen zâid); مُذْ، مُنْذُ mâzîde ibtidâ, hâlde zarfiyet; حَاشَا، خَلَا، عَدَا istisnâ.",
        "en": "The particle: what signifies a meaning in another. The jarr letter: what is coined to carry a verb, or a verb's meaning, over to what follows it. مِنْ beginning, explanation, partition (redundant in non-affirmative speech); إِلَى end (sometimes مَعَ); حَتَّى limit (often مَعَ); فِي containment; بِ contact, means, company, exchange, transitivity, containment (regularly redundant in the khabar of negation and question); لِ cause, appropriation (sometimes redundant); رُبَّ fewness; the wāw of oath on an overt noun when the verb is dropped; the tāʾ of oath only on the name of God; عَنْ distance and passing; عَلَى elevation; كَ likeness (sometimes redundant); مُذْ، مُنْذُ a beginning in the past, containment in the present; حَاشَا، خَلَا، عَدَا exception."},
  "ar": ["مَا دَلَّ عَلَى مَعْنًى فِي غَيْرِهِ", "مَا وُضِعَ لِلْإِفْضَاءِ بِفِعْلٍ أَوْ مَعْنَاهُ إِلَى مَا يَلِيهِ"], "notes": ["huruf-jarr", "al-harf-wa-huruf-al-jarr-fil-kafiya", "huruf-jarr-nawadir", "al-kalima-wal-kalam"], "story": "al-kafiya", "chapter": 28},
 {"n": 2, "q": {"tr": "Hurûf-i müşebbehe bi'l-fiil nelerdir? Ne cihetten fiile benzerler?", "en": "Which are the verb-like particles, and in what do they resemble the verb?"},
  "a": {"tr": "إِنَّ، أَنَّ، كَأَنَّ، لَكِنَّ، لَيْتَ، لَعَلَّ. Lafzan: üçlü, dörtlü, beşli ve fetha üzere mebnî oldukları için; mânen: kendilerinde fiil mânâsı olduğu için (إِنَّ ve أَنَّ tahkîk, كَأَنَّ teşbîh, لَكِنَّ istidrâk, لَيْتَ temennî, لَعَلَّ tereccî).",
        "en": "إِنَّ، أَنَّ، كَأَنَّ، لَكِنَّ، لَيْتَ، لَعَلَّ. In wording, being of three, four or five letters and built on the fatḥa; in meaning, carrying a verb's sense (إِنَّ and أَنَّ affirmation, كَأَنَّ likeness, لَكِنَّ correction, لَيْتَ wish, لَعَلَّ hope)."},
  "ar": ["إِنَّ وَأَنَّ وَكَأَنَّ وَلَكِنَّ وَلَيْتَ وَلَعَلَّ"], "notes": ["inna-wa-akhawatuha", "al-huruf-al-mushabbaha-bil-fil-fil-kafiya"], "story": "al-kafiya", "chapter": 29},
 {"n": 3, "q": {"tr": "Elif-nûn maddesinin nerelerde kesre ile okunması vâciptir?", "en": "Where must إِنَّ be read with kasra?"},
  "a": {"tr": "Cümle mevkiinde kesre, müfred mevkiinde fetha vâciptir. Kesre on yerde: ibtidâda (إِنَّ زَيْدًا قَائِمٌ); kasemin cevabında (وَاللهِ إِنَّ زَيْدًا قَائِمٌ); sıla makamında (مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ); muayyen ismin haberinde (زَيْدٌ إِنَّهُ قَائِمٌ); haberine ibtidâ lâmı giren cümlede (عَلِمْتُ إِنَّ زَيْدًا لَقَائِمٌ); zandan soyulmuş kavilden sonra (قُلْ إِنَّ اللهَ وَاحِدٌ); حَتَّى-i ibtidâiyyeden sonra; tasdîk harflerinden sonra (نَعَمْ إِنَّ زَيْدًا قَائِمٌ); iftitâh harflerinden sonra (أَلَا إِنَّ زَيْدًا قَائِمٌ); vâv-ı hâliyyeden sonra (وَإِنَّ فَرِيقًا مِنَ الْمُؤْمِنِينَ لَكَارِهُونَ).",
        "en": "Kasra where a sentence stands, fatḥa where a single noun would. Kasra in ten places: at the head (إِنَّ زَيْدًا قَائِمٌ); answering an oath (وَاللهِ إِنَّ زَيْدًا قَائِمٌ); in a relative clause (مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ); as khabar of a named subject (زَيْدٌ إِنَّهُ قَائِمٌ); when the lām of ibtidāʾ enters its khabar (عَلِمْتُ إِنَّ زَيْدًا لَقَائِمٌ); after a saying not meaning supposition (قُلْ إِنَّ اللهَ وَاحِدٌ); after the initiating حَتَّى; after the particles of assent (نَعَمْ إِنَّ زَيْدًا قَائِمٌ); after the particles of opening (أَلَا إِنَّ زَيْدًا قَائِمٌ); after the wāw of ḥāl (وَإِنَّ فَرِيقًا مِنَ الْمُؤْمِنِينَ لَكَارِهُونَ)."},
  "ar": ["إِنَّ زَيْدًا قَائِمٌ", "زَيْدٌ إِنَّهُ قَائِمٌ", "عَلِمْتُ إِنَّ زَيْدًا لَقَائِمٌ", "قُلْ إِنَّ اللهَ وَاحِدٌ"], "notes": ["inna-am-anna", "mawadi-kasr-inna"], "story": "al-kafiya", "chapter": 29},
 {"n": 4, "q": {"tr": "Elif-nûn maddesinin nerelerde fetha ile okunması vâciptir?", "en": "Where must أَنَّ be read with fatḥa?"},
  "a": {"tr": "On yerde: fâil olduğunda (بَلَغَنِي أَنَّكَ قَائِمٌ); mef'ûl olduğunda (عَلِمْتُ أَنَّ زَيْدًا قَائِمٌ); mübteda olduğunda (عِنْدِي أَنَّكَ قَائِمٌ); muzâfun ileyh olduğunda (اجْلِسْ حَيْثُ أَنَّ زَيْدًا جَالِسٌ); لَوْ'den sonra (لَوْ أَنَّكَ قَائِمٌ لَكَانَ كَذَا); لَوْلَا'dan sonra; mâ-i masdariyye-i tevkîtiyyeden sonra (اجْلِسْ مَا أَنَّ زَيْدًا قَائِمٌ); harf-i cerlerden sonra (عَجِبْتُ مِنْ أَنَّكَ قَائِمٌ); حَتَّى-i âtıfadan sonra (عَرَفْتُ أُمُورَكَ حَتَّى أَنَّكَ صَالِحٌ); مُذْ ve مُنْذُ'den sonra (مَا رَأَيْتُهُ مُذْ أَنَّكَ قَائِمٌ).",
        "en": "In ten places: as doer (بَلَغَنِي أَنَّكَ قَائِمٌ); as object (عَلِمْتُ أَنَّ زَيْدًا قَائِمٌ); as mubtadaʾ (عِنْدِي أَنَّكَ قَائِمٌ); as annexed-to (اجْلِسْ حَيْثُ أَنَّ زَيْدًا جَالِسٌ); after لَوْ (لَوْ أَنَّكَ قَائِمٌ لَكَانَ كَذَا); after لَوْلَا; after the temporal maṣdar-مَا (اجْلِسْ مَا أَنَّ زَيْدًا قَائِمٌ); after the jarr letters (عَجِبْتُ مِنْ أَنَّكَ قَائِمٌ); after the coordinating حَتَّى (عَرَفْتُ أُمُورَكَ حَتَّى أَنَّكَ صَالِحٌ); after مُذْ and مُنْذُ (مَا رَأَيْتُهُ مُذْ أَنَّكَ قَائِمٌ)."},
  "ar": ["بَلَغَنِي أَنَّكَ قَائِمٌ", "عَلِمْتُ أَنَّ زَيْدًا قَائِمٌ", "عِنْدِي أَنَّكَ قَائِمٌ", "عَجِبْتُ مِنْ أَنَّكَ قَائِمٌ"], "notes": ["inna-am-anna", "mawadi-fath-anna"], "story": "al-kafiya", "chapter": 29},
 {"n": 5, "q": {"tr": "İki takdirin câiz olduğu yerler nelerdir?", "en": "Where are both readings allowed?"},
  "a": {"tr": "İki takdirin (cümle ve müfred) câiz olduğu yerde iki emir (kesre ve fetha) de câizdir: fâ-i cezâ ve إِذَا-i müfâcâtdan sonra müfred takdiri de cümle takdiri de câiz olduğundan kesre de fetha da okunabilir.",
        "en": "Where either a sentence or a single noun may be supplied, either vowel may be read: after the fāʾ of the answer and the إِذَا of surprise both are supplied, so both kasra and fatḥa are allowed."},
  "ar": [], "notes": ["inna-am-anna", "mawadi-kasr-inna", "mawadi-fath-anna"], "story": "al-kafiya", "chapter": 29},
 {"n": 6, "q": {"tr": "Meksûr إِنَّ ve meftûh أَنَّ hafifletildiğinde ne lâzım gelir?", "en": "What follows when إِنَّ and أَنَّ are lightened?"},
  "a": {"tr": "Meksûr إِنَّ hafifletilince إِنْ kalır; haberine ibtidâ lâmı getirmek lâzımdır; amelden bozulması ve mübteda fiillerinden birinin üzerine girmesi câiz olur. Meftûh أَنَّ hafifletilince أَنْ kalır; mukadder zamir-i şanda ameli vâcip olur; mutlak olarak cümle üzerine girer; şart ve duâ dışındaki mutasarrıf fiille birlikte bir nefiy harfi ya da sîn, سَوْفَ veya قَدْ lâzım gelir.",
        "en": "Lightened, إِنَّ becomes إِنْ: the lām of ibtidāʾ must enter its khabar, its governing may lapse, and it may enter on one of the verbs of the mubtadaʾ. Lightened, أَنَّ becomes أَنْ: it must govern an implied pronoun of the matter, it enters on any sentence, and with a fully conjugating verb other than a condition or prayer it needs a negation, the sīn, سَوْفَ or قَدْ."},
  "ar": [], "notes": ["inna-wa-akhawatuha", "masail-inna-wal-mukhaffafa-fil-kafiya"], "story": "al-kafiya", "chapter": 30},
 {"n": 7, "q": {"tr": "Atıf harfleri nelerdir? Mânâları nelerdir?", "en": "Which are the coordinating particles, and what do they mean?"},
  "a": {"tr": "وَ، فَ، ثُمَّ، حَتَّى، أَوْ، إِمَّا، أَمْ، لَا، بَلْ، لَكِنْ. İlk dördü cem'iyyet içindir: وَ mutlak cem'iyyet; فَ tertip ile cem'iyyet; ثُمَّ ve حَتَّى mühlet ile tertip ve cem'iyyet. أَوْ، إِمَّا، أَمْ mübhem iki emirden biri içindir; لَا، بَلْ، لَكِنْ muayyen olduğu hâlde iki emirden biri içindir.",
        "en": "وَ، فَ، ثُمَّ، حَتَّى، أَوْ، إِمَّا، أَمْ، لَا، بَلْ، لَكِنْ. The first four join: وَ joins absolutely, فَ with order, ثُمَّ and حَتَّى with order and delay. أَوْ، إِمَّا، أَمْ are for one of two things left vague; لَا، بَلْ، لَكِنْ for one of two things made definite."},
  "ar": ["وَفَثُمَّ حَتَّى"], "notes": ["huruf-al-atf-fil-kafiya", "atf-nasaq", "al-atf-bil-huruf-wa-ahkamuh"], "story": "al-kafiya", "chapter": 31},
 {"n": 8, "q": {"tr": "Hurûf-i tenbîh, hurûf-i nidâ, hurûf-i îcâb nelerdir?", "en": "Which are the particles of alerting, of calling and of assent?"},
  "a": {"tr": "Tenbîh: أَلَا، أَمَا، هَا. Nidâ: يَا، أَيَا، هَيَا، أَيْ ve hemze — يَا umûmî, أَيَا ve هَيَا uzak için, أَيْ ve hemze yakın için. Îcâb: نَعَمْ، بَلَى، إِي، أَجَلْ، جَيْرِ، إِنَّ.",
        "en": "Alerting: أَلَا، أَمَا، هَا. Calling: يَا، أَيَا، هَيَا، أَيْ and the hamza — يَا general, أَيَا and هَيَا for the far, أَيْ and the hamza for the near. Assent: نَعَمْ، بَلَى، إِي، أَجَلْ، جَيْرِ، إِنَّ."},
  "ar": ["أَلَا وَأَمَا وَهَا", "نَعَمْ وَبَلَى وَإِي وَأَجَلْ"], "notes": ["huruf-tanbih", "al-mabni-ghayr-al-lazim-tawabi-al-munada-wa-huruf-al-nida-wa-ism-la-wal-mudari-bil-nun"], "story": "al-kafiya", "chapter": 32},
 {"n": 9, "q": {"tr": "Hurûf-i ziyâde, hurûf-i tefsîr, hurûf-i masdar, hurûf-i tahdîz nelerdir?", "en": "Which are the redundant particles, the particles of explanation, of the maṣdar, and of urging?"},
  "a": {"tr": "Ziyâde: إِنْ، أَنْ، مَا، لَا، مِنْ، بَ، لَ. Tefsîr: أَيْ، أَنْ — أَنْ, kavil mânâsındaki fiillere mahsustur. Masdar: مَا، أَنْ، أَنَّ. Tahdîz: هَلَّا، أَلَّا، لَوْلَا، لَوْمَا.",
        "en": "Redundant: إِنْ، أَنْ، مَا، لَا، مِنْ، the bāʾ and the lām. Explanation: أَيْ، أَنْ — the latter only after verbs meaning «say». Maṣdar: مَا، أَنْ، أَنَّ. Urging: هَلَّا، أَلَّا، لَوْلَا، لَوْمَا."},
  "ar": ["هَلَّا وَأَلَّا وَلَوْلَا وَلَوْمَا"], "notes": ["huruf-al-ziyada-fil-kafiya", "al-tahdid-wa-qad-wal-istifham-fil-kafiya", "an-masdariyya"], "story": "al-kafiya", "chapter": 33},
 {"n": 10, "q": {"tr": "Hurûf-i tevakku', istifhâm, şart ve red' nelerdir?", "en": "Which are the particles of expectation, question, condition and rebuke?"},
  "a": {"tr": "Tevakku': قَدْ — mâzî ve muzâride tahkîk; mâzîde tevakku' ve takrîb, muzâride taklîl ifade eder. İstifhâm: hemze ve هَلْ. Şart: إِنْ، لَوْ، أَمَّا — إِنْ mâzî ve muzâride istikbal için, لَوْ aksi için; ikisine lafzan ya da takdiren fiil lâzımdır; أَمَّا tafsîl içindir, fiili hazfedilip cümlenin cüzlerinden biri yerine konur. Red': كَلَّا.",
        "en": "Expectation: قَدْ — affirmation with past and present; with the past expectation and nearness, with the present fewness. Question: the hamza and هَلْ. Condition: إِنْ، لَوْ، أَمَّا — إِنْ makes past and present future, لَوْ the reverse; both need a verb, stated or supplied; أَمَّا is for detailing, its verb dropped and a part of the sentence put in its place. Rebuke: كَلَّا."},
  "ar": ["قَدْ", "كَلَّا"], "notes": ["al-tahdid-wa-qad-wal-istifham-fil-kafiya", "huruf-al-shart-fil-kafiya", "kalla-wa-ta-al-tanith-wal-tanwin-fil-kafiya", "qad-harf", "amma-tafsiliyya", "in-shartiyya"], "story": "al-kafiya", "chapter": 34},
 {"n": 11, "q": {"tr": "Tenvînin tarifi nedir? Kaç kısımdır?", "en": "How is tanwīn defined, and how many kinds has it?"},
  "a": {"tr": "Fiili te'kîd için olmayıp kelimenin âhirinin harekesine tâbi olarak gelen sâkin nûndur. Beş kısım: temekkün (kelimenin gayr-i munsarif olmadığına delâlet eder: كِتَابٌ), tenkîr (nekreliğe delâlet: كِتَابٌ), ivaz (muzâfun ileyhten ivaz: يَوْمَئِذٍ), mukâbele (cem'-i müzekker sâlimin nûnuna mukâbil cem'-i müenneste: مُسْلِمَاتٌ), terennüm (beyit ve mısra sonlarında).",
        "en": "A still nūn following the last letter's vowel, not for emphasising a verb. Five kinds: of establishment (showing the word is not barred from inflection: كِتَابٌ), of indefiniteness (كِتَابٌ), of compensation (for a dropped annexed-to: يَوْمَئِذٍ), of correspondence (matching the sound masculine plural's nūn in the feminine: مُسْلِمَاتٌ), of chanting (at the ends of verses)."},
  "ar": ["نُونٌ سَاكِنَةٌ تَتْبَعُ حَرَكَةَ الْآخِرِ لَا لِتَأْكِيدِ الْفِعْلِ", "يَوْمَئِذٍ"], "notes": ["kalla-wa-ta-al-tanith-wal-tanwin-fil-kafiya"], "story": "al-kafiya", "chapter": 35},
]
